<section class="content-page order-panel"><p class="eyebrow">SİPARİŞ BİLGİSİ</p><h1><?= e($order['order_no']) ?></h1><p>Sipariş durumu: <strong><?= e($order['status']) ?></strong> · Ödeme: <strong><?= e($order['payment_status']) ?></strong></p><h2>Ürünler</h2><?php foreach($orderItems as $item): ?><p><?= e($item['product_name']) ?> × <?= (int)$item['quantity'] ?> — <?= number_format((float)$item['unit_price']*(int)$item['quantity'],2,',','.') ?> ₺</p><?php endforeach; ?><h2>Toplam: <?= number_format((float)$order['total'],2,',','.') ?> ₺</h2><?php if($order['payment_status']!=='paid'): ?><div class="alert">Bu sipariş henüz ödenmedi. Ödeme sağlayıcısından doğrulanmış bildirim geldiğinde rezerve kodlar otomatik teslim edilecektir.</div><?php endif; ?><?php if($deliveredCodes): ?><h2>Dijital kodlarınız</h2><?php foreach($deliveredCodes as $code): ?><p class="delivered-code"><?= e(inventory_decrypt($code)) ?></p><?php endforeach; ?><?php endif; ?><a class="primary-link" href="<?= e(url()) ?>">Mağazaya dön</a></section>